import math

def solve_small_case(N):
    # Start with N ones
    blackboard = [1] * N

    # A wants to maximize N_final, B wants to minimize N_final.
    # Based on notes, B optimizes by using differences (or 0 if possible)
    # to quickly reduce the sum and keep numbers small.

    while len(blackboard) >= 2:
        S = sum(blackboard)

        # Check termination condition (1): one number z > S - z (i.e., 2z > S)
        for z in blackboard:
            if 2 * z > S:
                return len(blackboard)

        # If all zeros, termination condition (2) is met.
        if S == 0:
            return len(blackboard)

        # Player A chooses two numbers x and y (A is indifferent between choices
        # if B plays optimally, so we pick the first two for simulation).
        x = blackboard[0]
        y = blackboard[1]

        # Remove x and y
        blackboard = blackboard[2:]

        # Player B chooses z from {x+y, |x-y|} to minimize final N_final.
        # We follow the strategy observed in the notes: prioritize 0 if x=y.

        if x == y:
            z = abs(x - y)  # z = 0
        else:
            # For x != y, B chooses the difference |x-y| to keep the values small, 
            # facilitating faster reduction to 0s, which minimizes N_final.
            z = abs(x - y)

        # Add z back
        blackboard.append(z)

    # If the loop finishes because N < 2, and no termination condition was met, 
    # this should not happen unless N=1 initially, but we are testing N >= 2.
    return len(blackboard)

results = {}
for N in [2, 3, 4, 5]:
    result = solve_small_case(N)
    expected_pattern = math.ceil(N / 2)
    results[N] = {
        "simulation": result, 
        "expected": expected_pattern, 
        "match": result == expected_pattern
    }

print("Verification Results:")
for N, data in results.items():
    print(f"N={N}: Simulation result = {data['simulation']}, Pattern K = {data['expected']}. Match: {data['match']}")
